const lyricCache=new Map();
const normal=s=>String(s||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
let lyricRequest=0,extractBusy=false,lastExtraction=null;
const lyricPanel=document.createElement('section');
lyricPanel.className='lyric-search-panel';
lyricPanel.innerHTML='<div class="lyric-query"><label>곡명<input id="lyricsTitle" placeholder="정확한 곡명"></label><label>가수<input id="lyricsArtist" placeholder="가수 이름"></label><button id="fetchLyrics" type="button">가사 자동 찾기</button></div><p id="lyricsLookupStatus" role="status"></p><div id="lyricsCandidates"></div><p id="lyricsAttribution"></p>';
document.querySelector('.live-stage').before(lyricPanel);
const songOpen=openSheet;
openSheet=function(song){songOpen(song);lyricRequest++;$('fetchLyrics').disabled=false;$('lyricsCandidates').replaceChildren();$('lyricsLookupStatus').textContent='';const guess=guessSong(current);$('lyricsTitle').value=guess.title;$('lyricsArtist').value=guess.artist;showLyricSource();if(!current.audio&&current.sections.flatMap(s=>s[1]).every(c=>c==='N.C.')){$('sheetSource').textContent='LYRICS · AUDIO PRACTICE';$('sheetNote').textContent='이 곡의 코드는 아직 분석되지 않았습니다. 음원 파일 또는 추출한 MP3를 분석하면 추정 코드를 표시합니다.'}if(!current.lyrics?.length)findLyrics(false)};
function guessSong(song){if(song.audio&&song.artist==='내 음원 · 자동 코드 추정'){const bits=song.title.split(/\s+-\s+/);if(bits.length===2)return{artist:bits[0],title:bits[1]};return{title:song.title,artist:''}}return{title:song.title,artist:/전통|민요|편곡/.test(song.artist)?'':song.artist}}
function showLyricSource(){const source=current?.lyricSource;$('lyricsAttribution').replaceChildren();if(source){const a=document.createElement('a');a.href='https://lrclib.net/';a.target='_blank';a.rel='noopener noreferrer';a.textContent='가사 제공: LRCLIB · '+source.artist+' · '+(source.synced?'시간 정보 있음':'시간 정보 없음');$('lyricsAttribution').append(a)}}
async function findLyrics(manual){if(!current)return;const title=$('lyricsTitle').value.trim(),artist=$('lyricsArtist').value.trim(),songId=current.id,request=++lyricRequest;if(!title)return;$('fetchLyrics').disabled=true;$('lyricsLookupStatus').textContent='가사를 자동으로 찾고 있습니다…';$('lyricsCandidates').replaceChildren();try{const key=title+' '+artist;let records=lyricCache.get(key);if(!records){const response=await fetch('https://lrclib.net/api/search?q='+encodeURIComponent(key),{signal:AbortSignal.timeout(15000)});if(!response.ok)throw new Error('lookup');records=await response.json();if(!Array.isArray(records))throw new Error('lookup');lyricCache.set(key,records)}if(request!==lyricRequest||current?.id!==songId)return;const usable=records.filter(r=>r.syncedLyrics||r.plainLyrics||r.instrumental).slice(0,20);if(!usable.length){$('lyricsLookupStatus').textContent='등록된 가사를 찾지 못했습니다. 곡명·가수를 수정하거나 가사를 직접 입력해주세요.';return}const exact=usable.filter(r=>normal(r.trackName)===normal(title)&&artist&&normal(r.artistName)===normal(artist));const matched=exact.sort((a,b)=>Number(!!b.syncedLyrics)-Number(!!a.syncedLyrics)||Math.abs((a.duration||0)-(current.duration||a.duration))-Math.abs((b.duration||0)-(current.duration||b.duration)))[0];if(matched&&!current.lyrics?.length){applyLyricRecord(matched);return}$('lyricsLookupStatus').textContent=current.lyrics?.length?'찾은 가사를 선택하면 현재 가사를 바꿉니다.':'곡·가수와 버전을 확인해 가사를 선택해주세요.';usable.slice(0,8).forEach(r=>{const b=document.createElement('button');b.className='lyric-result';b.textContent=r.trackName+' · '+r.artistName+' · '+format(r.duration)+' · '+(r.instrumental?'연주곡':r.syncedLyrics?'싱크 가사':'일반 가사');b.onclick=()=>applyLyricRecord(r);$('lyricsCandidates').append(b)})}catch{if(request===lyricRequest&&current?.id===songId)$('lyricsLookupStatus').textContent='가사 서비스에 연결하지 못했습니다. 잠시 후 자동 찾기를 다시 누르거나 LRC를 불러와주세요.'}finally{if(request===lyricRequest)$('fetchLyrics').disabled=false}}
function applyLyricRecord(record){if(!current)return;let rows=record.syncedLyrics?T.parseLRC(record.syncedLyrics):[];const synced=rows.length>0;if(!synced){const lines=String(record.plainLyrics||'').split(/\r?\n/).map(s=>s.trim()).filter(Boolean);const length=record.duration||current.duration||duration();rows=lines.map((text,i)=>({time:length*i/lines.length,text}))}current.lyrics=rows;current.lyricSource={id:record.id,title:record.trackName,artist:record.artistName,synced};if(!current.duration&&!current.audio&&current.sections.flatMap(s=>s[1]).every(c=>c==='N.C.'))current.duration=record.duration||180;renderLyrics();saveEdits();showLyricSource();$('lyricsCandidates').replaceChildren();$('lyricsLookupStatus').textContent=record.instrumental?'가사 없는 연주곡으로 등록된 음원입니다.':synced?'싱크 가사를 자동 추가했습니다. 음반 버전이 다르면 가사 타이밍을 조정해주세요.':'가사를 추가했습니다. 시간 정보가 없어 임시로 균등 배치했습니다. 싱크 편집에서 맞춰주세요.'}
$('fetchLyrics').onclick=()=>findLyrics(true);
const externalOriginal=externalDialog;
externalDialog=function(song){externalOriginal(song);const b=document.createElement('button');b.className='primary';b.textContent='가사 자동 추가 · 연습 열기';b.onclick=()=>{$('dialog').close();openSheet({id:'song-'+normal(song.title+'-'+song.artist),title:song.title,artist:song.artist,key:'C',bpm:80,duration:song.duration||180,sections:[['코드 미분석 · 음원 분석 후 코드 표시',['N.C.']]]});$('sheetNote').textContent='이 곡의 코드는 아직 분석되지 않았습니다. 유튜브 음원 또는 내 파일을 분석하면 추정 코드를 표시합니다.'};$('dialogBody').append(b)};
const youtubeDialog=document.createElement('dialog');youtubeDialog.id='youtubeDialog';youtubeDialog.className='youtube-dialog';youtubeDialog.innerHTML='<button id="youtubeClose" class="dialog-close" aria-label="유튜브 창 닫기">×</button><div class="eyebrow">YOUTUBE TO YOUR PRACTICE</div><h2>링크 하나로, 연습 준비.</h2><label class="youtube-link">YouTube · YouTube Music 링크<input id="youtubeUrl" placeholder="https://www.youtube.com/watch?v=…"></label><p class="youtube-caption">10분 이하 공개 영상의 오디오를 MP3로 저장합니다. 다운로드할 수 있는 권한이 있는 영상에 사용하세요.</p><div class="extraction-actions"><button id="extractAudio" class="primary">MP3 음원 추출</button><button id="extractionSettings">서버 연결 설정</button></div><p id="extractStatus" role="status" aria-live="polite"></p><div id="extractionResult" hidden><strong id="extractedTitle"></strong><p id="extractedArtist"></p><div class="extraction-actions"><button id="downloadMp3" class="primary">MP3 다운로드</button><button id="analyzeMp3">코드 분석 · 가사 자동 추가</button></div><p>추출 파일은 서버에 잠시 보관한 뒤 삭제됩니다. 서버 재시작 시에도 삭제될 수 있습니다.</p></div><div id="audioServerSettings" hidden><label>음원 추출 서버 URL<input id="audioServerUrl" placeholder="https://your-service.onrender.com"></label><button id="saveAudioServer">연결 저장</button><p>서버가 연결되지 않으면 추출 기능을 사용할 수 없습니다.</p></div></dialog>';
document.body.append(youtubeDialog);
const youtubeButton=document.createElement('button');youtubeButton.type='button';youtubeButton.className='upload-btn';youtubeButton.textContent='↗ 유튜브 음원 · 다운로드';$('uploadBtn').before(youtubeButton);youtubeButton.onclick=()=>openYoutube('');
function openYoutube(url){$('youtubeUrl').value=url;$('extractStatus').textContent=extractBusy?'이전 음원을 처리하고 있습니다. 완료될 때까지 기다려주세요.':'';if(!extractBusy){lastExtraction=null;$('extractionResult').hidden=true}$('audioServerUrl').value=serverBase();$('audioServerSettings').hidden=!!serverBase();youtubeDialog.showModal()}
function serverBase(){let savedBase='';try{savedBase=localStorage.getItem('chordroom-audio-server')||''}catch{}return(savedBase||window.CHORDROOM_AUDIO_API||'').replace(/\/+$/,'')}
function validServer(value){try{const u=new URL(value);return !u.username&&!u.password&&!u.search&&!u.hash&&u.pathname==='/'&&(u.protocol==='https:'||(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))}catch{return false}}
$('youtubeClose').onclick=()=>youtubeDialog.close();$('extractionSettings').onclick=()=>$('audioServerSettings').hidden=!$('audioServerSettings').hidden;$('saveAudioServer').onclick=()=>{const v=$('audioServerUrl').value.trim();if(!validServer(v)){$('extractStatus').textContent='올바른 https 서버 주소를 입력해주세요.';return}try{localStorage.setItem('chordroom-audio-server',v.replace(/\/+$/,''));$('audioServerSettings').hidden=true;$('extractStatus').textContent='서버 주소를 저장했습니다.'}catch{$('extractStatus').textContent='이 브라우저는 연결 설정을 저장할 수 없습니다.'}};
const priorSearch=search;search=async function(){const text=$('query').value.trim();if(youtubeId(text)){openYoutube(text);return}return priorSearch()};
async function serverJson(base,path,options={}){const response=await fetch(base+path,{...options,signal:AbortSignal.timeout(90000)});let data;try{data=await response.json()}catch{throw new Error('음원 서버가 응답하지 않습니다. 무료 서버가 시작 중이면 잠시 후 다시 시도해주세요.')}if(!response.ok)throw new Error(data.message||'음원 서버 오류가 발생했습니다.');return data}
$('extractAudio').onclick=async()=>{if(extractBusy)return;const url=$('youtubeUrl').value.trim();if(!youtubeId(url)){$('extractStatus').textContent='올바른 YouTube 영상 링크를 입력해주세요.';return}const base=serverBase();if(!base||!validServer(base)){$('extractStatus').textContent='음원 추출 서버 연결이 필요합니다. 서버 주소를 먼저 설정해주세요.';$('audioServerSettings').hidden=false;return}extractBusy=true;lastExtraction=null;$('extractAudio').disabled=true;$('extractionResult').hidden=true;$('extractStatus').textContent='서버에 연결 중입니다. 무료 서버가 시작될 때는 시간이 걸릴 수 있습니다.';try{let job=await serverJson(base,'/api/extractions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const started=Date.now();while(job.status==='pending'||job.status==='processing'){if(Date.now()-started>300000)throw new Error('처리 시간이 길어지고 있습니다. 잠시 후 다시 시도해주세요.');$('extractStatus').textContent=job.message;await new Promise(r=>setTimeout(r,2500));job=await serverJson(base,'/api/extractions/'+encodeURIComponent(job.id))}if(job.status!=='ready')throw new Error(job.message||'음원 추출에 실패했습니다.');lastExtraction={...job,base};$('extractStatus').textContent=job.message;$('extractedTitle').textContent=job.title;$('extractedArtist').textContent=job.artist+' · '+format(job.duration)+' · MP3';$('extractionResult').hidden=false}catch(error){$('extractStatus').textContent=error.name==='TimeoutError'?'서버 응답 시간이 초과됐습니다. 잠시 후 다시 시도해주세요.':error.message||'서버 연결을 확인해주세요.'}finally{extractBusy=false;$('extractAudio').disabled=false}};
async function extractionBlob(){if(!lastExtraction)throw new Error('먼저 음원을 추출해주세요.');const response=await fetch(lastExtraction.base+lastExtraction.download,{signal:AbortSignal.timeout(90000)});if(!response.ok)throw new Error('파일이 만료됐습니다. 음원을 다시 추출해주세요.');return response.blob()}
$('downloadMp3').onclick=async()=>{const b=$('downloadMp3');b.disabled=true;try{const blob=await extractionBlob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=lastExtraction.title+'.mp3';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){$('extractStatus').textContent=e.message}finally{b.disabled=false}};
$('analyzeMp3').onclick=async()=>{const b=$('analyzeMp3');b.disabled=true;try{const result=lastExtraction,blob=await extractionBlob();youtubeDialog.close();await analyzeAudioFile(new File([blob],result.title+'.mp3',{type:'audio/mpeg'}),{title:result.title,artist:result.artist,source:'youtube'})}catch(e){$('extractStatus').textContent=e.message}finally{b.disabled=false}};
